Template instantiation and dependent names:
```c++
template <typename T>
class X {
public:
  void foo() { T a; }
};

int main() {
  X<int> x1; // T is resolved to int during instantiation
  X<double> x2; // T is resolved to double during instantiation
  return 0;
}
```

Example of two-phase name lookup and potential ambiguity:
```c++
namespace Y {
  typedef double T;
}

class D {
  typedef long T; 
public:
  void foo() { T a; } // T refers to D::T (inner scope) 
};

int main() {
  D d; d.foo();
  Y::T b; //explicitly use Y::T
}
```
